// Get Set-Cookie response header
const cookie = pm.response.headers.get("Set-Cookie");

console.log("Complete Cookie:", cookie);

// Store complete cookie
pm.environment.set("cookie", cookie);

// Extract XSRF-TOKEN
const xsrfMatch = cookie.match(/XSRF-TOKEN=([^;]+)/);

if (xsrfMatch) {
    const xsrfToken = decodeURIComponent(xsrfMatch[1]).trim();

    pm.environment.set("XSRF-TOKEN", xsrfToken);

    console.log("XSRF-TOKEN:", xsrfToken);
}

// Extract botble_session
const sessionMatch = cookie.match(/botble_session=([^;]+)/);

if (sessionMatch) {
    const botbleSession = decodeURIComponent(sessionMatch[1]).trim();

    pm.environment.set("botble_session", botbleSession);

    console.log("botble_session:", botbleSession);
}

// Verify saved variables
console.log("All cookies stored successfully");

